import { z } from "zod/v4";
var bulkEmailSchema = z.object({
	/** Which mailbox it goes out from. Order pages keep the default; the Bulk Email page seeds 'hello'. */
	sender: z.enum(["orders", "hello"]).default("orders"),
	recipients: z.array(z.object({
		email: z.email(),
		name: z.string().optional()
	})).min(1, { error: "Select at least one recipient." }),
	subject: z.string().min(1, { error: "Subject is required." }).max(255),
	message: z.string().min(1, { error: "Write a message." }).max(5e4)
});
//#endregion
export { bulkEmailSchema as t };
